// Firm reason: 1 (browser glue: adopts server-rendered Coax HTML nodes in place during first Wasm frame and preserves pre-hydration user input)
// In-place hydration helper for coax/web/dom-host.js (#14092).
// Adopts SSR elements generated by components/backend/html.coax without calling
// root.replaceChildren(), eliminating visual flicker and preserving text typed
// by the user into <input>/<textarea> controls before Wasm finished loading.

export function readInitialState(doc = globalThis.document) {
  const el = doc?.getElementById?.("coaxial-state");
  return el ? String(el.textContent || "") : "";
}

export function createHydrator(root) {
  const isSsr = Boolean(
    root &&
    (root.getAttribute?.("data-coax-ssr") === "1" || root.dataset?.coaxSsr === "1")
  );
  if (!isSsr) {
    return {
      active: false,
      adopt: () => null,
      hasDraft: () => false,
      finish: () => [],
    };
  }

  const ssrById = new Map();
  const adopted = new Set();
  const drafts = new Map();
  const existing = root.querySelectorAll ? root.querySelectorAll("[id]") : [];

  for (const el of existing) {
    if (!el.id || ssrById.has(el.id)) continue;
    ssrById.set(el.id, el);
    const tag = String(el.tagName || "").toUpperCase();
    if ((tag === "INPUT" || tag === "TEXTAREA") && el.type !== "file") {
      const initial = tag === "INPUT"
        ? (el.getAttribute?.("value") ?? el.defaultValue ?? "")
        : (el.defaultValue ?? "");
      const live = typeof el.value === "string" ? el.value : "";
      if (live !== initial) {
        drafts.set(el.id, live);
      }
    }
  }

  const hydrator = {
    active: true,
    adoptedCount: 0,
    prunedCount: 0,

    adopt(tag, id) {
      if (!hydrator.active || !id) return null;
      const el = ssrById.get(id);
      if (!el || adopted.has(el)) return null;
      if (String(el.tagName || "").toLowerCase() !== String(tag || "").toLowerCase()) return null;
      adopted.add(el);
      hydrator.adoptedCount += 1;
      return el;
    },

    hasDraft(id) {
      return hydrator.active && drafts.has(id);
    },

    finish(els) {
      if (!hydrator.active) return [];
      hydrator.active = false;
      for (const el of ssrById.values()) {
        if (!adopted.has(el)) {
          el.remove?.();
          hydrator.prunedCount += 1;
        }
      }
      root.removeAttribute?.("data-coax-ssr");
      root.setAttribute?.("data-coax-hydrated", "1");

      const pendingDrafts = [];
      if (drafts.size > 0 && Array.isArray(els)) {
        for (let slot = 0; slot < els.length; slot++) {
          const el = els[slot];
          if (!el || !drafts.has(el.id)) continue;
          pendingDrafts.push({ slot, id: el.id, value: drafts.get(el.id) });
        }
      }
      drafts.clear();
      return pendingDrafts;
    },
  };

  return hydrator;
}
